#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// Specialized for n_heads=8, d_head=64, d_state=16, block_len=64
// X_blocks: [B, C, L, H, P]  A_blocks_orig: [B, C, L, H] -> [B, H, C, L]
// B_blocks: [B, C, L, H, N]  C_blocks: [B, C, L, H, N]
// Output Y: [B, C*L, H, P]

#define D_HEAD 64
#define D_STATE 16
#define BLOCK_LEN 64
#define N_HEADS 8

// Kernel 1: compute Y_diag
// Y_diag[b,c,l,h,p] = sum_{s<=l, n} C[b,c,l,h,n] * B[b,c,s,h,n] * L[b,h,c,l,s] * X[b,c,s,h,p]
// where L[b,h,c,l,s] = exp(segsum(A_blocks[b,h,c,:])[l,s])
//   = exp(A_cumsum[b,h,c,l] - A_cumsum[b,h,c,s]) for s<=l, else 0
// Grid: (B*C*H, L, P_groups) where each thread handles one (b,c,h,l,p)
// We'll use grid(B*C*H, BLOCK_LEN) each thread handles one p in [0,P)
// Actually let's do: grid(B*C*H*BLOCK_LEN, D_HEAD/32) block(32)

__global__ void ydiag_kernel(
    const float* __restrict__ X_blocks,   // [B,C,L,H,P]
    const float* __restrict__ A_cumsum,   // [B,H,C,L]
    const float* __restrict__ B_blocks,   // [B,C,L,H,N]
    const float* __restrict__ C_blocks,   // [B,C,L,H,N]
    float* __restrict__ Y_diag,           // [B,C,L,H,P]
    int B_sz, int C_sz
) {
    // grid: (B_sz*C_sz*N_HEADS*BLOCK_LEN, D_HEAD/32)
    // each block of 32 threads handles one p-group of 32
    int idx = blockIdx.x;
    int p_group = blockIdx.y;  // 0 or 1
    int tid = threadIdx.x;     // 0..31

    int l   = idx % BLOCK_LEN; idx /= BLOCK_LEN;
    int h   = idx % N_HEADS;   idx /= N_HEADS;
    int c   = idx % C_sz;      idx /= C_sz;
    int b   = idx;

    if (b >= B_sz) return;

    int p = p_group * 32 + tid;
    if (p >= D_HEAD) return;

    // Load C[b,c,l,h,:] into registers
    float C_reg[D_STATE];
    // C_blocks layout: [B,C,L,H,N]
    int c_base = ((b * C_sz + c) * BLOCK_LEN + l) * N_HEADS * D_STATE + h * D_STATE;
    #pragma unroll
    for (int n = 0; n < D_STATE; n++) {
        C_reg[n] = C_blocks[c_base + n];
    }

    // A_cumsum layout: [B,H,C,L]
    float acl = A_cumsum[((b * N_HEADS + h) * C_sz + c) * BLOCK_LEN + l];

    float acc = 0.0f;
    // sum over s = 0..l
    for (int s = 0; s <= l; s++) {
        float acs = A_cumsum[((b * N_HEADS + h) * C_sz + c) * BLOCK_LEN + s];
        float decay = __expf(acl - acs);

        // dot C_reg . B[b,c,s,h,:]
        int b_base = ((b * C_sz + c) * BLOCK_LEN + s) * N_HEADS * D_STATE + h * D_STATE;
        float cb_dot = 0.0f;
        #pragma unroll
        for (int n = 0; n < D_STATE; n++) {
            cb_dot += C_reg[n] * B_blocks[b_base + n];
        }

        // X[b,c,s,h,p]
        float xval = X_blocks[((b * C_sz + c) * BLOCK_LEN + s) * N_HEADS * D_HEAD + h * D_HEAD + p];
        acc += decay * cb_dot * xval;
    }

    Y_diag[((b * C_sz + c) * BLOCK_LEN + l) * N_HEADS * D_HEAD + h * D_HEAD + p] = acc;
