// states[b,c,h,p,n] = sum_l B[b,c,l,h,n] * decay_states[b,h,c,l] * X[b,c,l,h,p]
// decay_states[b,h,c,l] = exp(A_cumsum[b,h,c,-1] - A_cumsum[b,h,c,l])
// Grid: (B_sz*C_sz*N_HEADS, D_HEAD) each thread handles one (b,c,h,p), reduces over l and n
// Better: grid(B_sz*C_sz*N_HEADS*D_HEAD, D_STATE) each thread one n, one p
// states layout: [B,C,H,P,N]
__global__ void states_kernel(
    const float* __restrict__ X_blocks,   // [B,C,L,H,P]
    const float* __restrict__ A_cumsum,   // [B,H,C,L]
    const float* __restrict__ B_blocks,   // [B,C,L,H,N]
    float* __restrict__ states,           // [B,C,H,P,N]
    int B_sz, int C_sz
) {
