    int idx = blockIdx.x;
    int n = blockIdx.y;  // 0..D_STATE-1
    int tid = threadIdx.x; // unused, single thread per block

    int p   = idx % D_HEAD;   idx /= D_HEAD;
    int h   = idx % N_HEADS;  idx /= N_HEADS;
    int c   = idx % C_sz;     idx /= C_sz;
    int b   = idx;

    if (b >= B_sz) return;
    if (n >= D_STATE) return;

    float ac_last = A_cumsum[((b * N_HEADS + h) * C_sz + c) * BLOCK_LEN + (BLOCK_LEN - 1)];

    float acc = 0.0f;
    for (int l = 0; l < BLOCK_LEN; l++) {
        float acl = A_cumsum[((b * N_HEADS + h) * C_sz + c) * BLOCK_LEN + l];
        float decay = __expf(ac_last - acl);
        float bval = B_blocks[((b * C_sz + c) * BLOCK_LEN + l) * N_HEADS * D_STATE + h * D_STATE + n];
        float xval = X_blocks[((b * C_sz + c) * BLOCK_LEN + l) * N_HEADS * D_HEAD + h * D_HEAD + p];
        acc += bval * decay * xval;
    }

    // states[b,c,h,p,n]
    states[((b * C_sz + c) * N_HEADS * D_HEAD + h * D_HEAD + p) * D_STATE + n] = acc;
