// Kernel 3: inter-chunk recurrence + Y_off
// For small C_sz (=2 in benchmark), do this sequentially per (b,h)
// new_states[b,z,h,p,n] = sum_c decay_chunk[b,h,z,c] * states_cat[b,c,h,p,n]
// where states_cat = cat([initial_states, states], dim=1) -> [B, C+1, H, P, N]
// decay_chunk[b,h,z,c] = exp(segsum(pad(A_cumsum[:,:,:,-1], (1,0))))[b,h,z,c]
//   for z,c: lower-triangular: exp(ac_end[c] - ac_end[z]) for c<=z, 0 else
//   where ac_end[0] = 0 (padded), ac_end[i+1] = A_cumsum[b,h,i,-1]
// new_states has shape [B, C+1, H, P, N], then states = new_states[:,:-1]
// Y_off[b,c,l,h,p] = sum_n C[b,c,l,h,n] * states[b,c,h,p,n] * state_decay_out[b,h,c,l]
//   state_decay_out = exp(A_cumsum)

// We'll compute new_states in a kernel, then Y_off in another

// Kernel 3a: compute new_states
// Grid: (B_sz*(C_sz+1)*N_HEADS*D_HEAD, D_STATE)
__global__ void new_states_kernel(
    const float* __restrict__ states_cat,  // [B, C+1, H, P, N] (includes initial)
    const float* __restrict__ ac_end,      // [B, H, C+1] padded cumsum endpoints
    float* __restrict__ new_states,        // [B, C+1, H, P, N]
    int B_sz, int C_sz_p1  // C_sz+1
) {
    int idx = blockIdx.x;
    int n = blockIdx.y;

    int p  = idx % D_HEAD;    idx /= D_HEAD;
    int h  = idx % N_HEADS;   idx /= N_HEADS;
    int z  = idx % C_sz_p1;   idx /= C_sz_p1;
    int b  = idx;

    if (b >= B_sz || n >= D_STATE) return;

    // decay_chunk[b,h,z,c] for c=0..z: exp(ac_end[b,h,c] - ac_end[b,h,z]) from segsum semantics
    // segsum on vector v of length C+1: result[z,c] = v[c] - v[z] (lower tri, c<=z) after prefix
    // ac_end[b,h,:] has shape C+1: [0, A_cumsum[b,h,0,-1], A_cumsum[b,h,1,-1], ...]
    float ace_z = ac_end[(b * N_HEADS + h) * C_sz_p1 + z];

    float acc = 0.0f;
    for (int c = 0; c <= z; c++) {
        float ace_c = ac_end[(b * N_HEADS + h) * C_sz_p1 + c];
        float dc = __expf(ace_c - ace_z);
        float sv = states_cat[((b * C_sz_p1 + c) * N_HEADS * D_HEAD + h * D_HEAD + p) * D_STATE + n];
        acc += dc * sv;
    }

    new_states[((b * C_sz_p1 + z) * N_HEADS * D_HEAD + h * D_HEAD + p) * D_STATE + n] = acc;
}

// Kernel 4: Y_off
// Y_off[b,c,l,h,p] = sum_n C[b,c,l,h,n] * states[b,c,h,p,n] * exp(A_cumsum[b,h,c,l])
// Grid: (B_sz*C_sz*BLOCK_LEN*N_HEADS, D_HEAD/32) block(32)
__global__ void yoff_kernel(
    const float* __restrict__ C_blocks,   // [B,C,L,H,N]
    const float* __restrict__ states,     // [B,C,H,P,N]  (new_states[:,:-1])
    const float* __restrict__ A_cumsum,   // [B,H,C,L]
    float* __restrict__ Y_off,            // [B,C,L,H,P]
    int B_sz, int C_sz
) {
    int idx = blockIdx.x;
    int p_group = blockIdx.y;
    int tid = threadIdx.x;

    int l   = idx % BLOCK_LEN; idx /= BLOCK_LEN;
    int h   = idx % N_HEADS;   idx /= N_HEADS;
    int c   = idx % C_sz;      idx /= C_sz;
    int b   = idx;

    if (b >= B_sz) return;

    int p = p_group * 32 + tid;
    if (p >= D_HEAD) return;

    float sdo = __expf(A_cumsum[((b * N_HEADS + h) * C_sz + c) * BLOCK_LEN + l]);

    // load C[b,c,l,h,:]
    float C_reg[D_STATE];
    int c_base = ((b * C_sz + c) * BLOCK_LEN + l) * N_HEADS * D_STATE + h * D_STATE;
    #pragma unroll
    for (int n = 0; n < D_STATE; n++) {
        C_reg[n] = C_blocks[c_base + n];
    }

    // sum_n C_reg[n] * states[b,c,h,p,n]
    float acc = 0.0f;
    int st_base = ((b * C_sz + c) * N_HEADS * D_HEAD + h * D_HEAD + p) * D_STATE;
    #pragma unroll
    for (int n = 0; n < D_STATE; n++) {
