    TORCH_CHECK(X.is_contiguous() && A.is_contiguous() && B.is_contiguous() && C.is_contiguous(), "All tensors must be contiguous");
    TORCH_CHECK(X.scalar_type() == torch::kFloat32, "Only float32 supported");

    int B_sz = X.size(0);
    int seq_len = X.size(1);
    int H = X.size(2);
    int P = X.size(3);
    int C_sz = seq_len / block_len;
    int N = B.size(3);

    TORCH_CHECK(H == N_HEADS && P == D_HEAD && N == D_STATE && block_len == BLOCK_LEN,
