    // X_blocks: [B, C_sz, L, H, P]
    auto X_blocks = X.view({B_sz, C_sz, (int)block_len, H, P}).contiguous();
    // A: [B, seq, H] -> A_blocks: [B, C_sz, L, H] -> [B, H, C_sz, L]
    auto A_blocks = A.view({B_sz, C_sz, (int)block_len, H}).permute({0,3,1,2}).contiguous();
    // B_blocks: [B, C_sz, L, H, N]
