    auto A_cumsum = torch::cumsum(A_blocks, /*dim=*/3).contiguous();

    // Allocate outputs
    auto Y_diag = torch::zeros({B_sz, C_sz, (int)block_len, H, P}, opts);
    auto Y_off_t = torch::zeros({B_sz, C_sz, (int)block_len, H, P}, opts);
    auto states_raw = torch::zeros({B_sz, C_sz, H, P, N}, opts);

    // Launch ydiag_kernel
    {
        dim3 grid(B_sz * C_sz * H * (int)block_len, D_HEAD / 32);
        dim3 block(32);
        ydiag_kernel<<<grid, block>>>(
            X_blocks.data_ptr<float>(),
            A_cumsum.data_ptr<float>(),
            B_blocks.data_ptr<float>(),
            C_blocks_t.data_ptr<float>(),
            Y_diag.data_ptr<float>(),
            B_sz, C_sz
