                    self.d_head == 64 and
                    self.d_state == 16 and
                    self.block_len == 64 and
                    (initial_states is None or (initial_states.is_cuda and initial_states.is_contiguous() and initial_states.dtype == torch.float32))):
                    return _stark_get_extension().mamba2returny_forward(
                        X.contiguous(),
                        self.A.contiguous(),
                        self.B.contiguous(),
                        self.C.contiguous(),
                        initial_states.contiguous() if initial_states is not None else None,
                        self.block_len
                    )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        X_blocks, A_blocks, B_blocks, C_blocks = [
                    rearrange(x, "b (c l) ... -> b c l ...", l=self.block_len)
                    for x in (X, self.A, self.B, self.C)
                ]
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        A_blocks = rearrange(A_blocks, "b c l h -> b h c l")
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        A_cumsum = torch.cumsum(A_blocks, dim=-1)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        L = torch.exp(self.segsum(A_blocks))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        Y_diag = torch.einsum("bclhn,bcshn,bhcls,bcshp->bclhp", 
                                     C_blocks, B_blocks, L, X_blocks)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        decay_states = torch.exp((A_cumsum[:, :, :, -1:] - A_cumsum))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_8>>>
        states = torch.einsum("bclhn,bhcl,bclhp->bchpn", 
                                    B_blocks, decay_states, X_blocks)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_9>>>
        if initial_states is None:
                    initial_states = torch.zeros_like(states[:, :1])
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_10>>>
        states = torch.cat([initial_states, states], dim=1)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_11>>>
        decay_chunk = torch.exp(self.segsum(F.pad(A_cumsum[:, :, :, -1], (1, 0))))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_12>>>
        new_states = torch.einsum("bhzc,bchpn->bzhpn", decay_chunk, states)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_13>>>
        states = new_states[:, :-1]
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_14>>>
        state_decay_out = torch.exp(A_cumsum)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_15>>>
        Y_off = torch.einsum('bclhn,bchpn,bhcl->bclhp', 
                                   C_blocks, states, state_decay_out)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_16>>>
        Y = rearrange(Y_diag + Y_off, "b c l h p -> b (c l) h p")
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_17>>>
        return Y
